\begin{ex}%[9D2C2-2]
Cho $a, b, c >0$ và $a+b+c=10$. Biểu thức $ \left(1+\dfrac{1}{a} \right) \left(1+\dfrac{1}{b} \right) \left(1+\dfrac{1}{c} \right)$ đạt giá trị nhỏ nhất khi nào?

\choice
{ Khi $ a = b =4, c = 2 $ }
   { Khi $ a = b =\dfrac{15}{4} ,c = \dfrac{5}{2} $ }
     { \True Khi $ a = b = c = \dfrac{10}{3} $ }
    { Khi $ a = b = \dfrac{5}{2} ,c = 5 $ }
\loigiai{
$\left(1+\dfrac{1}{a} \right) \left(1+\dfrac{1}{b} \right) \left(1+\dfrac{1}{c} \right)  =  1+\dfrac{1}{a}+\dfrac{1}{b}+\dfrac{1}{c}+ \dfrac{1}{bc}+\dfrac{1}{ac}+\dfrac{1}{ab}+\dfrac{1}{abc}$.\\
Áp dụng BĐT AM-GM cho các số dương ta được:\\
$\dfrac{1}{a} + \dfrac{1}{b} + \dfrac{1}{c} \ge \dfrac{3}{\sqrt[3]{abc}} $\\
$\dfrac{1}{ab}+\dfrac{1}{bc}+\dfrac{1}{ac} \ge \dfrac{3}{\sqrt[3]{(abc)^2}}$\\
$abc \le \left( \dfrac{a+b+c}{3} \right)^3 = \dfrac{1000}{27} $\\
Dấu bằng xảy ra khi: $ a = b = c = \dfrac{10}{3} $
}\end{ex}

