\begin{ex}%[9D2C2-2]
Giá trị nhỏ nhất của biểu thức $\dfrac{x^{4} + 5 x^{2} + 9}{7 x^{2}}$ với $x \ne 0$
\choice
{ ${\dfrac{26}{7}}$ }
   { $6$ }
     { \True ${\dfrac{11}{7}}$ }
    { ${\dfrac{15}{7}}$ }
\loigiai{
$\dfrac{x^{4} + 5 x^{2} + 9}{7 x^{2}} =  \dfrac{x^{2}}{7} + \dfrac{5}{7} + \dfrac{9}{7 x^{2}}   $\\
$=\left( \dfrac{x^{2}}{7}+  \dfrac{9}{7 x^{2}} \right) + \dfrac{5}{7} $\\
$\ge 2. \sqrt{\dfrac{x^{2}}{7}\dfrac{9}{7 x^{2}}}+  \dfrac{5}{7}=2.\dfrac{3}{7} +\dfrac{5}{7} = \dfrac{11}{7} $
}\end{ex}

